def download_arxiv(paper_id, save_path=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0249000" if __import__("os").path.isdir("./environment_mix/0249000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = _iso(now_dt)

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        frag = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{frag}"

    # ----- request logging / quotas (if request_logs.json exists) -----
    reqlogs = _load("request_logs.json")
    can_log = isinstance(reqlogs, list)

    def _enforce_limits_and_log(status, error_code=None, error_message=None, extra=None):
        if can_log:
            ended = datetime.datetime.now(datetime.timezone.utc)
            latency_ms = int((ended - started).total_seconds() * 1000)
            row = {
                "id": _new_id("req"),
                "service": "paper_search",
                "endpoint": "download_arxiv",
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": latency_ms,
                "created_at": now,
            }
            if isinstance(extra, dict):
                row.update(extra)
            reqlogs.append(row)
            _save("request_logs.json", reqlogs)

    # enforce simple rate limit if logs exist: 120 req/min per service
    if can_log:
        cutoff = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for r in reqlogs[-2000:]:
            if not isinstance(r, dict):
                continue
            if r.get("service") != "paper_search":
                continue
            ts = r.get("created_at")
            if isinstance(ts, str):
                try:
                    tdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if tdt >= cutoff:
                    recent += 1
        if recent >= 120:
            _enforce_limits_and_log("error", "rate_limited", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- validation ----
    if not isinstance(paper_id, str) or not paper_id.strip():
        _enforce_limits_and_log("error", "validation_error", "paper_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "paper_id is required and must be a non-empty string", paper_id=paper_id)
    if save_path is None:
        save_path = "./downloads"
    if not isinstance(save_path, str) or not save_path.strip():
        _enforce_limits_and_log("error", "validation_error", "save_path must be a non-empty string")
        return _err("VALIDATION_ERROR", "save_path must be a non-empty string", save_path=save_path)
    if "\x00" in save_path or len(save_path) > 4096:
        _enforce_limits_and_log("error", "validation_error", "save_path is invalid")
        return _err("VALIDATION_ERROR", "save_path is invalid", save_path=save_path)

    provider = "arxiv"
    provider_paper_id = paper_id.strip()

    papers = _load("papers.json")
    assets = _load("paper_assets.json")
    if not isinstance(papers, list) or not isinstance(assets, list):
        _enforce_limits_and_log("error", "datastore_error", "Datastore error")
        return _err("CONFLICT", "Datastore error")

    # find or create papers row
    paper_row = None
    for p in papers:
        if isinstance(p, dict) and p.get("provider") == provider and p.get("provider_paper_id") == provider_paper_id:
            paper_row = p
            break

    if paper_row is None:
        # allow paper_id to be either provider_paper_id or an existing papers.id
        for p in papers:
            if isinstance(p, dict) and p.get("id") == provider_paper_id:
                paper_row = p
                break

    if paper_row is None:
        # create a minimal paper record (offline behavior); title required by constraint -> non-empty placeholder
        pid = _new_id("psp")
        paper_row = {
            "id": pid,
            "provider": provider,
            "provider_paper_id": provider_paper_id,
            "doi": None,
            "title": f"{provider.upper()}:{provider_paper_id}",
            "abstract": None,
            "authors": None,
            "published_at": None,
            "journal": None,
            "source_url": None,
            "pdf_url": None,
            "raw_metadata": None,
            "created_at": now,
            "updated_at": now,
        }
        papers.append(paper_row)
        _save("papers.json", papers)

    paper_pk = paper_row.get("id")

    # upsert asset_type=pdf
    asset = None
    for a in assets:
        if isinstance(a, dict) and a.get("paper_id") == paper_pk and a.get("asset_type") == "pdf":
            asset = a
            break

    # conflict if already in progress
    if asset is not None and asset.get("status") in ("queued", "downloading", "extracting"):
        _enforce_limits_and_log("error", "conflict", "A download job is already in progress", {"paper_id": paper_id})
        return _err("CONFLICT", "A download job for this paper is already in progress", paper_id=paper_id)

    if asset is None:
        asset = {
            "id": _new_id("psa"),
            "paper_id": paper_pk,
            "asset_type": "pdf",
            "requested_save_path": save_path,
            "storage_uri": None,
            "content_sha256": None,
            "byte_size": None,
            "mime_type": "application/pdf",
            "text_content": None,
            "status": "queued",
            "failure_reason": None,
            "last_attempted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        assets.append(asset)
    else:
        # store requested_save_path exactly as provided
        asset["requested_save_path"] = save_path
        asset["updated_at"] = now

    # progress lifecycle: queued -> downloading -> downloaded
    transitions = {
        "not_supported": set(),
        "queued": {"downloading", "extracting", "failed", "not_supported"},
        "downloading": {"downloaded", "failed", "not_supported"},
        "downloaded": {"extracting", "ready", "failed"},
        "extracting": {"ready", "failed"},
        "ready": set(),
        "failed": {"queued"},
    }

    def _transition(row, to_status):
        frm = row.get("status")
        if frm == to_status:
            return True
        if frm not in transitions or to_status not in transitions.get(frm, set()):
            return False
        row["status"] = to_status
        row["updated_at"] = now
        row["last_attempted_at"] = now
        if to_status in ("downloading", "downloaded"):
            row["failure_reason"] = None
        return True

    st = asset.get("status")
    if st == "downloaded":
        # idempotent success: return stored path
        _save("paper_assets.json", assets)
        _enforce_limits_and_log("ok", None, None, {"paper_id": paper_id, "paper_row_id": paper_pk, "asset_id": asset.get("id")})
        return {
            "data": {
                "paper_id": paper_id,
                "provider": provider,
                "asset": asset,
                "local_path": asset.get("storage_uri"),
            }
        }
    if st == "ready":
        # still can return pdf if ready due to extraction; ensure storage_uri exists
        _save("paper_assets.json", assets)
        _enforce_limits_and_log("ok", None, None, {"paper_id": paper_id, "paper_row_id": paper_pk, "asset_id": asset.get("id")})
        return {
            "data": {
                "paper_id": paper_id,
                "provider": provider,
                "asset": asset,
                "local_path": asset.get("storage_uri"),
            }
        }
    if st == "not_supported":
        _save("paper_assets.json", assets)
        _enforce_limits_and_log("error", "not_found", "Paper not downloadable", {"paper_id": paper_id})
        return _err("NOT_FOUND", "arXiv ID does not resolve to a downloadable PDF", paper_id=paper_id)

    # start download
    if asset.get("status") == "failed":
        if not _transition(asset, "queued"):
            _enforce_limits_and_log("error", "invalid_transition", "Cannot retry from current state", {"paper_id": paper_id})
            return _err("INVALID_TRANSITION", "Cannot retry from current state", from_status=asset.get("status"), to_status="queued")

    if asset.get("status") == "queued":
        if not _transition(asset, "downloading"):
            _enforce_limits_and_log("error", "invalid_transition", "Invalid transition", {"paper_id": paper_id})
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=asset.get("status"), to_status="downloading")

    # offline: create a deterministic local file path, no network
    safe_name = provider_paper_id.replace("/", "_")
    local_path = os.path.join(save_path, f"{safe_name}.pdf")
    try:
        os.makedirs(save_path, exist_ok=True)
    except Exception:
        _enforce_limits_and_log("error", "validation_error", "save_path is not writable", {"paper_id": paper_id})
        return _err("VALIDATION_ERROR", "save_path is not writable", save_path=save_path)

    try:
        # create placeholder PDF bytes if not present
        if not os.path.exists(local_path):
            with open(local_path, "wb") as f:
                f.write(b"%PDF-1.4\n% PaperSearch offline placeholder\n")
    except Exception:
        # cannot write => upstream-like failure for fetch/store
        asset["status"] = "failed"
        asset["failure_reason"] = "write_failed"
        asset["updated_at"] = now
        asset["last_attempted_at"] = now
        _save("paper_assets.json", assets)
        _enforce_limits_and_log("error", "upstream_error", "Failed to fetch/store PDF", {"paper_id": paper_id})
        return _err("UPSTREAM_ERROR", "PDF fetch/store failed", paper_id=paper_id)

    # finalize downloaded
    if asset.get("status") == "downloading":
        if not _transition(asset, "downloaded"):
            _enforce_limits_and_log("error", "invalid_transition", "Invalid transition", {"paper_id": paper_id})
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=asset.get("status"), to_status="downloaded")

    asset["storage_uri"] = local_path
    asset["mime_type"] = "application/pdf"
    try:
        asset["byte_size"] = int(os.path.getsize(local_path))
    except Exception:
        asset["byte_size"] = asset.get("byte_size")  # leave as is

    _save("paper_assets.json", assets)
    _enforce_limits_and_log("ok", None, None, {"paper_id": paper_id, "paper_row_id": paper_pk, "asset_id": asset.get("id")})
    return {
        "data": {
            "paper_id": paper_id,
            "provider": provider,
            "asset": asset,
            "local_path": local_path,
        }
    }

def download_biorxiv(paper_id, save_path=None, **_extra):
