        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = _iso(now_dt)

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        frag = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{frag}"

    reqlogs = _load("request_logs.json")
    can_log = isinstance(reqlogs, list)

    def _log(status, error_code=None, error_message=None, extra=None):
        if not can_log:
            return
        ended = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": _new_id("req"),
            "service": "paper_search",
            "endpoint": "read_arxiv_paper",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        reqlogs.append(row)
        _save("request_logs.json", reqlogs)

    if can_log:
        cutoff = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for r in reqlogs[-2000:]:
            if isinstance(r, dict) and r.get("service") == "paper_search":
                ts = r.get("created_at")
                if isinstance(ts, str):
                    try:
                        tdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if tdt >= cutoff:
                        recent += 1
        if recent >= 120:
            _log("error", "rate_limited", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    if not isinstance(paper_id, str) or not paper_id.strip():
        _log("error", "validation_error", "paper_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "paper_id is required and must be a non-empty string", paper_id=paper_id)
    if save_path is None:
        save_path = "./downloads"
    if not isinstance(save_path, str) or not save_path.strip():
        _log("error", "validation_error", "save_path must be a non-empty string")
        return _err("VALIDATION_ERROR", "save_path must be a non-empty string", save_path=save_path)
    if "\x00" in save_path or len(save_path) > 4096:
        _log("error", "validation_error", "save_path is invalid")
        return _err("VALIDATION_ERROR", "save_path is invalid", save_path=save_path)

    provider = "arxiv"
    provider_paper_id = paper_id.strip()

    papers = _load("papers.json")
    assets = _load("paper_assets.json")
    if not isinstance(papers, list) or not isinstance(assets, list):
        _log("error", "datastore_error", "Datastore error")
        return _err("CONFLICT", "Datastore error")

    # resolve paper row: accept either provider_paper_id or papers.id
    paper_row = None
    for p in papers:
        if isinstance(p, dict) and p.get("provider") == provider and p.get("provider_paper_id") == provider_paper_id:
            paper_row = p
            break
    if paper_row is None:
        for p in papers:
            if isinstance(p, dict) and p.get("id") == provider_paper_id and p.get("provider") == provider:
                paper_row = p
                break
    if paper_row is None:
        # create minimal row so we can attach assets (offline)
        pid = _new_id("psp")
        paper_row = {
            "id": pid,
            "provider": provider,
            "provider_paper_id": provider_paper_id,
            "doi": None,
            "title": f"{provider.upper()}:{provider_paper_id}",
            "abstract": None,
            "authors": None,
            "published_at": None,
            "journal": None,
            "source_url": None,
            "pdf_url": None,
            "raw_metadata": None,
            "created_at": now,
            "updated_at": now,
        }
        papers.append(paper_row)
        _save("papers.json", papers)

    paper_pk = paper_row.get("id")

    transitions = {
        "not_supported": set(),
        "queued": {"downloading", "extracting", "failed", "not_supported"},
        "downloading": {"downloaded", "failed", "not_supported"},
        "downloaded": {"extracting", "ready", "failed"},
        "extracting": {"ready", "failed"},
        "ready": set(),
        "failed": {"queued"},
    }

    def _transition(row, to_status):
        frm = row.get("status")
        if frm == to_status:
            return True
        if frm not in transitions or to_status not in transitions.get(frm, set()):
            return False
        row["status"] = to_status
        row["updated_at"] = now
        row["last_attempted_at"] = now
        if to_status in ("downloading", "downloaded", "extracting", "ready"):
            row["failure_reason"] = None
        return True

    # ensure pdf asset downloaded (reuse download logic locally)
    pdf_asset = None
    for a in assets:
        if isinstance(a, dict) and a.get("paper_id") == paper_pk and a.get("asset_type") == "pdf":
            pdf_asset = a
            break
    if pdf_asset is None:
        pdf_asset = {
            "id": _new_id("psa"),
            "paper_id": paper_pk,
            "asset_type": "pdf",
            "requested_save_path": save_path,
            "storage_uri": None,
            "content_sha256": None,
            "byte_size": None,
            "mime_type": "application/pdf",
            "text_content": None,
            "status": "queued",
            "failure_reason": None,
            "last_attempted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        assets.append(pdf_asset)
    else:
        pdf_asset["requested_save_path"] = save_path
        pdf_asset["updated_at"] = now

    if pdf_asset.get("status") == "not_supported":
        _save("paper_assets.json", assets)
        _log("error", "not_found", "Not downloadable", {"paper_id": paper_id})
        return _err("NOT_FOUND", "The arXiv ID does not resolve to a downloadable PDF.", paper_id=paper_id)

    if pdf_asset.get("status") in ("queued", "failed"):
        if pdf_asset.get("status") == "failed":
            if not _transition(pdf_asset, "queued"):
                _log("error", "invalid_transition", "Cannot retry pdf")
                return _err("INVALID_TRANSITION", "Cannot retry from current state", from_status=pdf_asset.get("status"), to_status="queued")
        if not _transition(pdf_asset, "downloading"):
            _log("error", "invalid_transition", "Invalid pdf transition")
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=pdf_asset.get("status"), to_status="downloading")

        safe_name = provider_paper_id.replace("/", "_")
        local_path = os.path.join(save_path, f"{safe_name}.pdf")
        try:
            os.makedirs(save_path, exist_ok=True)
        except Exception:
            _log("error", "validation_error", "save_path is not writable", {"paper_id": paper_id})
            return _err("VALIDATION_ERROR", "save_path is not writable", save_path=save_path)
        try:
            if not os.path.exists(local_path):
                with open(local_path, "wb") as f:
                    f.write(b"%PDF-1.4\n% PaperSearch offline placeholder\n")
        except Exception:
            pdf_asset["status"] = "failed"
            pdf_asset["failure_reason"] = "write_failed"
            pdf_asset["updated_at"] = now
            pdf_asset["last_attempted_at"] = now
            _save("paper_assets.json", assets)
            _log("error", "upstream_error", "Failed to fetch/store PDF", {"paper_id": paper_id})
            return _err("UPSTREAM_ERROR", "PDF fetch/store failed", paper_id=paper_id)

        if not _transition(pdf_asset, "downloaded"):
            _log("error", "invalid_transition", "Invalid pdf transition")
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=pdf_asset.get("status"), to_status="downloaded")
        pdf_asset["storage_uri"] = local_path
        pdf_asset["mime_type"] = "application/pdf"
        try:
            pdf_asset["byte_size"] = int(os.path.getsize(local_path))
        except Exception:
            pass

    if pdf_asset.get("status") == "downloading":
        _log("error", "conflict", "PDF is currently downloading", {"paper_id": paper_id})
        return _err("CONFLICT", "PDF is currently downloading; retry later", paper_id=paper_id)

    # ensure extracted_text asset ready
    txt_asset = None
    for a in assets:
        if isinstance(a, dict) and a.get("paper_id") == paper_pk and a.get("asset_type") == "extracted_text":
            txt_asset = a
            break

    if txt_asset is None:
        txt_asset = {
            "id": _new_id("psa"),
            "paper_id": paper_pk,
            "asset_type": "extracted_text",
            "requested_save_path": save_path,
            "storage_uri": None,
            "content_sha256": None,
            "byte_size": None,
            "mime_type": "text/plain",
            "text_content": None,
            "status": "queued",
            "failure_reason": None,
            "last_attempted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        assets.append(txt_asset)
    else:
        txt_asset["requested_save_path"] = save_path
        txt_asset["updated_at"] = now

    if txt_asset.get("status") == "ready" and isinstance(txt_asset.get("text_content"), str):
        _save("paper_assets.json", assets)
        _log("ok", None, None, {"paper_id": paper_id, "paper_row_id": paper_pk, "text_asset_id": txt_asset.get("id")})
        return {"data": {"paper_id": paper_id, "provider": provider, "text": txt_asset.get("text_content"), "assets": {"pdf": pdf_asset, "extracted_text": txt_asset}}}

    if txt_asset.get("status") == "not_supported":
        _save("paper_assets.json", assets)
        _log("error", "not_supported", "Text extraction not supported", {"paper_id": paper_id})
        return _err("CONFLICT", "Text extraction not supported for this paper", paper_id=paper_id)

    if txt_asset.get("status") in ("downloading",):
        _log("error", "conflict", "Asset not readable yet", {"paper_id": paper_id})
        return _err("CONFLICT", "Paper is not readable yet; retry later", paper_id=paper_id)

    # progress to extracting then ready
    if txt_asset.get("status") == "failed":
        if not _transition(txt_asset, "queued"):
            _log("error", "invalid_transition", "Cannot retry extraction", {"paper_id": paper_id})
            return _err("INVALID_TRANSITION", "Cannot retry from current state", from_status=txt_asset.get("status"), to_status="queued")

    if txt_asset.get("status") == "queued":
        if not _transition(txt_asset, "extracting"):
            _log("error", "invalid_transition", "Invalid transition", {"paper_id": paper_id})
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=txt_asset.get("status"), to_status="extracting")

    # offline extraction: synthesize from available metadata
    title = paper_row.get("title") or f"{provider.upper()}:{provider_paper_id}"
    abstract = paper_row.get("abstract")
    authors = paper_row.get("authors")
    body = []
    body.append(f"Title: {title}")
    if isinstance(authors, list) and authors:
        body.append("Authors: " + ", ".join([str(x) for x in authors if isinstance(x, (str, int, float))]))
    if isinstance(abstract, str) and abstract.strip():
        body.append("\nAbstract:\n" + abstract.strip())
    else:
        body.append("\nAbstract:\n(abstract not available in offline datastore)")
    body.append(f"\nSource: {provider} / {provider_paper_id}")
    body.append(f"PDF: {pdf_asset.get('storage_uri')}")
    text = "\n".join(body)

    txt_asset["mime_type"] = "text/plain"
    txt_asset["text_content"] = text
    txt_asset["storage_uri"] = None
    try:
        txt_asset["byte_size"] = len(text.encode("utf-8"))
    except Exception:
        txt_asset["byte_size"] = None

    if not _transition(txt_asset, "ready"):
        _log("error", "invalid_transition", "Invalid transition", {"paper_id": paper_id})
        return _err("INVALID_TRANSITION", "Invalid status transition", from_status=txt_asset.get("status"), to_status="ready")

    _save("paper_assets.json", assets)
    _log("ok", None, None, {"paper_id": paper_id, "paper_row_id": paper_pk, "text_asset_id": txt_asset.get("id")})
    return {"data": {"paper_id": paper_id, "provider": provider, "text": text, "assets": {"pdf": pdf_asset, "extracted_text": txt_asset}}}

