    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = _iso(now_dt)

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        frag = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{frag}"

    reqlogs = _load("request_logs.json")
    can_log = isinstance(reqlogs, list)

    def _log(status, error_code=None, error_message=None, extra=None):
        if not can_log:
            return
        ended = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": _new_id("req"),
            "service": "paper_search",
            "endpoint": "read_medrxiv_paper",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        reqlogs.append(row)
        _save("request_logs.json", reqlogs)

    if can_log:
        cutoff = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for r in reqlogs[-2000:]:
            if isinstance(r, dict) and r.get("service") == "paper_search":
                ts = r.get("created_at")
                if isinstance(ts, str):
                    try:
                        tdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if tdt >= cutoff:
                        recent += 1
        if recent >= 120:
            _log("error", "rate_limited", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    if not isinstance(paper_id, str) or not paper_id.strip():
        _log("error", "validation_error", "paper_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "paper_id is required and must be a non-empty string", paper_id=paper_id)
    if save_path is None:
        save_path = "./downloads"
    if not isinstance(save_path, str) or not save_path.strip():
        _log("error", "validation_error", "save_path must be a non-empty string")
        return _err("VALIDATION_ERROR", "save_path must be a non-empty string", save_path=save_path)
    if "\x00" in save_path or len(save_path) > 4096:
        _log("error", "validation_error", "save_path is invalid")
        return _err("VALIDATION_ERROR", "save_path is invalid", save_path=save_path)

    provider = "medrxiv"
