def list_search_queries(provider=None, status=None, query_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0249000" if __import__("os").path.isdir("./environment_mix/0249000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    providers = {"arxiv", "pubmed", "biorxiv", "medrxiv", "google_scholar"}
    statuses = {"queued", "running", "succeeded", "failed"}

    if provider is not None and (not isinstance(provider, str) or provider not in providers):
        return _err("VALIDATION_ERROR", "Invalid provider filter.", allowed=sorted(providers))
    if status is not None and (not isinstance(status, str) or status not in statuses):
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(statuses))
    if query_contains is not None and (not isinstance(query_contains, str)):
        return _err("VALIDATION_ERROR", "query_contains must be a string when provided.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    # Decode cursor as base64-encoded JSON: {"ts": "...", "id": "..."} or {"offset": n}
    start_after = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            start_after = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = _load("search_queries.json")
    # filter
    out = []
    qc = query_contains.lower() if isinstance(query_contains, str) and query_contains else None
    for r in rows:
        if provider is not None and r.get("provider") != provider:
            continue
        if status is not None and r.get("status") != status:
            continue
        if qc is not None:
            q = r.get("query")
            if not isinstance(q, str) or qc not in q.lower():
                continue
        out.append(r)

    # sort reverse-chronological by created_at then id
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    out.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc), r.get("id") or ""), reverse=True)

    # apply cursor (start after a specific (created_at,id))
    if start_after and isinstance(start_after, dict) and "ts" in start_after and "id" in start_after:
        ts = start_after.get("ts")
        cid = start_after.get("id")
        # find first index strictly after this tuple in the sorted list
        filtered = []
        passed = False
        for r in out:
            if not passed:
                if r.get("created_at") == ts and r.get("id") == cid:
                    passed = True
                continue
            filtered.append(r)
        out2 = filtered if passed else out
        out = out2
    elif start_after and isinstance(start_after, dict) and "offset" in start_after:
        off = start_after.get("offset")
        if not isinstance(off, int) or off < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        out = out[off:]

    page = out[:limit]
    has_more = len(out) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"ts": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": len(out) if not cursor else None,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

