    providers = {"arxiv", "pubmed", "biorxiv", "medrxiv", "google_scholar"}
    if provider is not None and (not isinstance(provider, str) or provider not in providers):
        return _err("VALIDATION_ERROR", "Invalid provider filter.", allowed=sorted(providers))
    if doi is not None and not isinstance(doi, str):
        return _err("VALIDATION_ERROR", "doi must be a string when provided.")
    if provider_paper_id is not None and not isinstance(provider_paper_id, str):
        return _err("VALIDATION_ERROR", "provider_paper_id must be a string when provided.")
    if title_contains is not None and not isinstance(title_contains, str):
        return _err("VALIDATION_ERROR", "title_contains must be a string when provided.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("datetime must be a string")
        return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))

    pa = None
    pb = None
    if published_after is not None:
        try:
            pa = _parse_dt(published_after)
        except Exception:
            return _err("VALIDATION_ERROR", "published_after must be an RFC3339 date-time string.")
    if published_before is not None:
        try:
            pb = _parse_dt(published_before)
        except Exception:
            return _err("VALIDATION_ERROR", "published_before must be an RFC3339 date-time string.")
    if pa and pb and pb < pa:
        return _err("VALIDATION_ERROR", "published_before must be >= published_after.")

    start_after = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            start_after = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = _load("papers.json")

    tc = title_contains.lower() if isinstance(title_contains, str) and title_contains else None

    def _published_ok(row):
        if pa is None and pb is None:
            return True
        s = row.get("published_at")
        if not isinstance(s, str):
            return False
        try:
            dt = _parse_dt(s)
        except Exception:
            return False
        if pa is not None and not (dt > pa):
            return False
        if pb is not None and not (dt < pb):
            return False
        return True

    out = []
    for r in rows:
        if provider is not None and r.get("provider") != provider:
            continue
        if doi is not None and r.get("doi") != doi:
            continue
        if provider_paper_id is not None and r.get("provider_paper_id") != provider_paper_id:
            continue
        if tc is not None:
            t = r.get("title")
            if not isinstance(t, str) or tc not in t.lower():
                continue
        if not _published_ok(r):
            continue
        out.append(r)

    # reverse-chronological by created_at then id
    def _safe_dt(s):
        try:
            return _parse_dt(s) if isinstance(s, str) else None
        except Exception:
            return None

    out.sort(key=lambda r: (_safe_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc), r.get("id") or ""), reverse=True)

    if start_after and isinstance(start_after, dict) and "ts" in start_after and "id" in start_after:
        ts = start_after.get("ts")
        cid = start_after.get("id")
        filtered = []
        passed = False
        for r in out:
            if not passed:
                if r.get("created_at") == ts and r.get("id") == cid:
                    passed = True
                continue
            filtered.append(r)
        out = filtered if passed else out
    elif start_after and isinstance(start_after, dict) and "offset" in start_after:
        off = start_after.get("offset")
        if not isinstance(off, int) or off < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        out = out[off:]

    page = out[:limit]
    has_more = len(out) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"ts": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": len(out) if not cursor else None,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def get_paper(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0249000" if __import__("os").path.isdir("./environment_mix/0249000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = _iso(now_dt)

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        frag = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{frag}"

    reqlogs = _load("request_logs.json")
    can_log = isinstance(reqlogs, list)

    def _log(status, error_code=None, error_message=None, extra=None):
        if not can_log:
            return
        ended = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": _new_id("req"),
            "service": "paper_search",
            "endpoint": "get_paper",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        reqlogs.append(row)
        _save("request_logs.json", reqlogs)

    # Validate input: any non-empty string is acceptable; even if it "looks like" another id type, treat as NOT_FOUND.
    if not isinstance(id, str) or not id.strip():
        _log("error", "validation_error", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)

    wanted = id.strip()

    papers_data = _load("papers.json")
    if isinstance(papers_data, dict) and isinstance(papers_data.get("rows"), list):
        papers_rows = papers_data.get("rows")
    elif isinstance(papers_data, list):
        papers_rows = papers_data
    else:
        _log("error", "datastore_error", "papers datastore is not readable")
        return _err("CONFLICT", "Datastore error: papers is not readable")

    found = None
    for row in papers_rows:
        if isinstance(row, dict) and row.get("id") == wanted:
            found = row
            break

    if not found:
        _log("error", "not_found", "Paper not found", extra={"paper_id": wanted})
        return _err("NOT_FOUND", "Paper not found", id=wanted)

    _log("success", extra={"paper_id": wanted})
    return {"paper": found}

def list_paper_assets(paper_id=None, asset_type=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0249000" if __import__("os").path.isdir("./environment_mix/0249000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                    "service": "paper_search",
                    "endpoint": "list_paper_assets",
                    "credential_id": None,
                    "status": status_s,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            try:
                _save("request_logs.json", logs)
            except Exception:
                pass

    allowed_asset_types = {"pdf", "extracted_text"}
    allowed_statuses = {"not_supported", "queued", "downloading", "downloaded", "extracting", "ready", "failed"}

    if paper_id is not None and (not isinstance(paper_id, str) or not paper_id.strip()):
        _log("error", "validation_error", "paper_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string")

    if asset_type is not None:
        if not isinstance(asset_type, str) or asset_type not in allowed_asset_types:
            _log("error", "validation_error", "asset_type is invalid")
            return _err("VALIDATION_ERROR", "asset_type is invalid", allowed=sorted(list(allowed_asset_types)))

    if status is not None:
        if not isinstance(status, str) or status not in allowed_statuses:
            _log("error", "validation_error", "status is invalid")
            return _err("VALIDATION_ERROR", "status is invalid", allowed=sorted(list(allowed_statuses)))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("error", "validation_error", "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("error", "validation_error", "limit must be between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("error", "validation_error", "cursor must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("start"), int):
                _log("error", "validation_error", "cursor is invalid")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start = obj["start"]
            if start < 0:
                _log("error", "validation_error", "cursor is invalid")
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            _log("error", "validation_error", "cursor is invalid")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    assets = _load("paper_assets.json")
    if not isinstance(assets, list):
        _log("error", "parse_error", "paper_assets datastore is not a list")
        return _err("CONFLICT", "Datastore error")

    # Filter
    filtered = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if paper_id is not None and a.get("paper_id") != paper_id:
            continue
        if asset_type is not None and a.get("asset_type") != asset_type:
            continue
        if status is not None and a.get("status") != status:
            continue
        filtered.append(a)

    # Deterministic ordering: created_at then id
    def _k(r):
        ca = r.get("created_at") or ""
        rid = r.get("id") or ""
        return (ca, rid)

    filtered.sort(key=_k)

    total = len(filtered)
    page = filtered[start : start + limit]
    next_start = start + len(page)
    has_more = next_start < total

    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "start": next_start}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8")

    _log("ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def get_current_user(api_key, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0249000" if __import__("os").path.isdir("./environment_mix/0249000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = _iso(now_dt)

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        frag = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{frag}"

    # Request logs are optional in this datastore; log if present as list or {"rows":[...]}.
    reqlogs_data = _load("request_logs.json")
    if isinstance(reqlogs_data, dict) and isinstance(reqlogs_data.get("rows"), list):
        reqlogs_rows = reqlogs_data["rows"]
        reqlogs_container = reqlogs_data
        can_log = True
    elif isinstance(reqlogs_data, list):
        reqlogs_rows = reqlogs_data
        reqlogs_container = None
        can_log = True
    else:
        reqlogs_rows = []
        reqlogs_container = None
        can_log = False

    def _persist_logs():
        if not can_log:
            return
        if reqlogs_container is not None:
            reqlogs_container["rows"] = reqlogs_rows
            _save("request_logs.json", reqlogs_container)
        else:
            _save("request_logs.json", reqlogs_rows)

    def _log(status, credential_id=None, error_code=None, error_message=None, extra=None):
        if not can_log:
            return
        ended = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": _new_id("req"),
            "service": "paper_search",
            "endpoint": "get_current_user",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        reqlogs_rows.append(row)
        _persist_logs()

    # Validate input
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", None, "validation_error", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    presented = api_key.strip()

    # Basic rate limit (observable dynamics) based on request logs, if available:
    # 300 requests / minute per credential_id (if known) else per presented api_key string.
    RATE_LIMIT_PER_MIN = 300
    if can_log:
        cutoff = now_dt - datetime.timedelta(seconds=60)

        def _parse_ts(v):
            if not isinstance(v, str):
                return None
            try:
                if v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None

        recent = 0
        for r in reqlogs_rows[-5000:]:
            if not isinstance(r, dict):
                continue
            if r.get("service") != "paper_search":
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None or ts < cutoff:
                continue
            # If we don't know credential_id yet, approximate by matching any existing presented key stored in logs.
            # Some deployments may log api_key; others only credential_id. We'll use both if present.
            if r.get("credential_id") == presented or r.get("api_key") == presented:
                recent += 1
        if recent >= RATE_LIMIT_PER_MIN:
            _log("error", None, "rate_limited", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Authenticate:
    # This datastore (per provided schema) doesn't include an auth/credentials collection.
    # Real behavior requirement: when a credential parameter exists, authenticate against a credential row's
    # client-visible value OR id; never against a hash/ciphertext. Since no credential table exists here,
    # we treat any non-empty api_key as accepted for this offline datastore, and we still produce quota usage
    # from request logs (if present). This avoids refusing well-formed calls due to missing auth tables.
    credential_id = presented  # best-effort stable identifier for logging/usage attribution

    # Quota/usage: compute last 60s and last 24h counts from logs (if available).
    usage = {"requests_last_minute": None, "requests_last_24h": None, "rate_limit_per_minute": RATE_LIMIT_PER_MIN}
    if can_log:
        cutoff_60 = now_dt - datetime.timedelta(seconds=60)
        cutoff_24h = now_dt - datetime.timedelta(hours=24)

        def _parse_ts(v):
            if not isinstance(v, str):
                return None
            try:
                if v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None

        c60 = 0
        c24 = 0
        for r in reqlogs_rows[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("service") != "paper_search":
                continue
            # attribute by credential_id when present; otherwise ignore
            rid = r.get("credential_id")
            if rid is None:
                continue
            if rid != credential_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff_24h:
                c24 += 1
                if ts >= cutoff_60:
                    c60 += 1

        usage["requests_last_minute"] = c60
        usage["requests_last_24h"] = c24

    # Log success before returning
    _log("success", credential_id=credential_id)

    return {
        "user": {
            "id": credential_id,
            "type": "api_key",
        },
        "scopes": ["paper_search:read", "paper_search:write"],
        "quota": usage,
    }
